public void makeReadOnly() {
        if (_readOnly)
            return;

        lock();
        try {
            // check again
            if (_readOnly)
                return;
            _readOnly = true;

            Log log = _conf.getLog(OpenJPAConfiguration.LOG_RUNTIME);
            if (log.isInfoEnabled())
                log.info(getFactoryInitializationBanner());
            if (log.isTraceEnabled()) {
                Map props = _conf.toProperties(true);
                String lineSep = J2DoPrivHelper.getLineSeparator();
                StringBuffer buf = new StringBuffer();
                Map.Entry entry;
                for (Iterator itr = props.entrySet().iterator();
                    itr.hasNext();) {
                    entry = (Map.Entry) itr.next();
                    buf.append(entry.getKey()).append(": ").
                        append(entry.getValue());
                    if (itr.hasNext())
                        buf.append(lineSep);
                }
                log.trace(_loc.get("factory-properties", buf.toString()));
            }

            // setup transient state
            setup();

            // register the metdata repository to auto-load persistent types
            // and make sure types are enhanced
            MetaDataRepository repos = _conf.getMetaDataRepositoryInstance();
            repos.setValidate(repos.VALIDATE_RUNTIME, true);
            repos.setResolve(repos.MODE_MAPPING_INIT, true);
            PCRegistry.addRegisterClassListener(repos);

            // freeze underlying configuration and eagerly initialize to
            // avoid synchronization
            _conf.setReadOnly(Configuration.INIT_STATE_FREEZING);
            _conf.instantiateAll();

            // fire an event for all the broker factory listeners
            // registered on the configuration.
            _conf.getBrokerFactoryEventManager().fireEvent(
                new BrokerFactoryEvent(this,
                    BrokerFactoryEvent.BROKER_FACTORY_CREATED));
        } finally {
            unlock();
        }
    }

public void doDynamic(StaplerRequest request, StaplerResponse response) throws ServletException, IOException {
        if (("/" + originalFileName).equals(request.getRestOfPath())) {
            AbstractBuild build = (AbstractBuild)request.findAncestor(AbstractBuild.class).getObject();
            File fileParameter = getLocationUnderBuild(build);

            if (!ALLOW_FOLDER_TRAVERSAL_OUTSIDE_WORKSPACE) {
                File fileParameterFolder = getFileParameterFolderUnderBuild(build);

                //TODO can be replaced by Util#isDescendant in 2.80+
                Path child = fileParameter.getAbsoluteFile().toPath().normalize();
                Path parent = fileParameterFolder.getAbsoluteFile().toPath().normalize();
                if (!child.startsWith(parent)) {
                    throw new IllegalStateException("The fileParameter tried to escape the expected folder: " + location);
                }
            }

            if (fileParameter.isFile()) {
                try (InputStream data = Files.newInputStream(fileParameter.toPath())) {
                    long lastModified = fileParameter.lastModified();
                    long contentLength = fileParameter.length();
                    if (request.hasParameter("view")) {
                        response.serveFile(request, data, lastModified, contentLength, "plain.txt");
                    } else {
                        response.serveFile(request, data, lastModified, contentLength, originalFileName);
                    }
                } catch (InvalidPathException e) {
                    throw new IOException(e);
                }
            }
        }
    }

