private Priority calculateMetricPriority(Metric metric){
		Priority priority;
		if (isMetricHighPriority(metric)) {
			priority = Priority.HIGH;
		} else if (isMetricModeratePriority(metric)) {
			priority = Priority.NORMAL;
		} else {
			priority = Priority.LOW;
		}

		return priority;
	}

