public JsonBuilder append(final Collection< ? > col)
  {
    if (col == null) {
      sb.append("[]");
      return this;
    }
    // Format: [["1.1", "1.2", ...],["2.1", "2.2", ...]]
    sb.append("[\n");
    String separator = "\n";
    for (final Object os : col) {
      sb.append(separator);
      separator = ",\n";
      if (os instanceof Object[]) { // Multiple properties
        append((Object[]) os);
      } else { // Only one property
        append(transform(os));
      }
    }
    sb.append("]"); // end data
    return this;
  }

