@Override
    public Principal authenticate(String username, String clientDigest,
                                  String nonce, String nc, String cnonce,
                                  String qop, String realm,
                                  String md5a2) {

        // In digest auth, digests are always lower case
        String md5a1 = getDigest(username, realm);
        if (md5a1 == null)
            return null;
        md5a1 = md5a1.toLowerCase(Locale.ENGLISH);
        String serverDigestValue;
        if (qop == null) {
            serverDigestValue = md5a1 + ":" + nonce + ":" + md5a2;
        } else {
            serverDigestValue = md5a1 + ":" + nonce + ":" + nc + ":" +
                    cnonce + ":" + qop + ":" + md5a2;
        }

        byte[] valueBytes = null;
        try {
            valueBytes = serverDigestValue.getBytes(getDigestCharset());
        } catch (UnsupportedEncodingException uee) {
            log.error("Illegal digestEncoding: " + getDigestEncoding(), uee);
            throw new IllegalArgumentException(uee.getMessage());
        }

        String serverDigest = MD5Encoder.encode(ConcurrentMessageDigest.digestMD5(valueBytes));

        if (log.isDebugEnabled()) {
            log.debug("Digest : " + clientDigest + " Username:" + username
                    + " ClientDigest:" + clientDigest + " nonce:" + nonce
                    + " nc:" + nc + " cnonce:" + cnonce + " qop:" + qop
                    + " realm:" + realm + "md5a2:" + md5a2
                    + " Server digest:" + serverDigest);
        }

        if (serverDigest.equals(clientDigest)) {
            return getPrincipal(username);
        }

        return null;
    }

private static int unescapedCharRev(String s, int rightIncl) {
    if (rightIncl < 0) {
      return 0;
    }
    // \?
    // \01
    // \012
    // \x00
    // \u0000
    for (int i = 1; i < 6; ++i) {
      int left = rightIncl - i;
      if (left < 0) { break; }
      if (s.charAt(left) == '\\') {
        // If there are an odd number of '\\' then decode.
        int n = 1;
        while (left - n >= 0 && s.charAt(left - n) == '\\') {
          ++n;
        }
        if ((n & 1) == 0) {
          int unescaped = unescapedChar(s, left);
          if ((unescaped >>> 16) == i) {
            return unescaped;
          }
        }
        break;
      }
    }
    return 0x10000 | s.charAt(rightIncl);
  }

