public void testArrayClassPollutionBlockedByPattern() throws Exception {
        // given
        final String pollution1 = "model.class.classLoader.jarPath";
        final String pollution2 = "model['class']['classLoader']['jarPath']";
        final String pollution3 = "model[\"class\"]['classLoader']['jarPath']";
        final String pollution4 = "class.classLoader.jarPath";
        final String pollution5 = "class['classLoader']['jarPath']";
        final String pollution6 = "class[\"classLoader\"]['jarPath']";

        loadConfigurationProviders(new XWorkConfigurationProvider(), new XmlConfigurationProvider("xwork-param-test.xml"));
        final Map<String, Object> params = new HashMap<String, Object>() {
            {
                put(pollution1, "bad");
                put(pollution2, "bad");
                put(pollution3, "bad");
                put(pollution4, "bad");
                put(pollution5, "bad");
                put(pollution6, "bad");
            }
        };

        final Map<String, Boolean> excluded = new HashMap<String, Boolean>();
        ParametersInterceptor pi = new ParametersInterceptor() {

            @Override
            protected boolean isExcluded(String paramName) {
                boolean result = super.isExcluded(paramName);
                excluded.put(paramName, result);
                return result;
            }

        };

        container.inject(pi);
        ValueStack vs = ActionContext.getContext().getValueStack();

        // when
        ValidateAction action = new ValidateAction();
        pi.setParameters(action, vs, params);

        // then
        assertEquals(0, action.getActionMessages().size());
        assertTrue(excluded.get(pollution1));
        assertTrue(excluded.get(pollution2));
        assertTrue(excluded.get(pollution3));
        assertTrue(excluded.get(pollution4));
        assertTrue(excluded.get(pollution5));
        assertTrue(excluded.get(pollution6));
    }

public static String autoGenerateStyleMap(TypeSystemDescription aTypeSystem) {
    // styles used in automatically generated style maps

    final String[] STYLES = { "color:black; background:lightblue;",
        "color:black; background:lightgreen;", "color:black; background:orange;",
        "color:black; background:yellow;", "color:black; background:pink;",
        "color:black; background:salmon;", "color:black; background:cyan;",
        "color:black; background:violet;", "color:black; background:tan;",
        "color:white; background:brown;", "color:white; background:blue;",
        "color:white; background:green;", "color:white; background:red;",
        "color:white; background:mediumpurple;" };

    TypeDescription[] types = aTypeSystem.getTypes();

    // generate style map by mapping each type to a background color
    StringBuffer buf = new StringBuffer();

    buf.append("<?xml version=\"1.0\" encoding=\"ISO-8859-1\"?>\n");
    buf.append("<styleMap>\n");

    for (int i = 0; i < types.length; i++) {
      String outputType = types[i].getName();
      String label = outputType;
      int lastDot = outputType.lastIndexOf('.');
      if (lastDot > -1) {
        label = outputType.substring(lastDot + 1);
      }

      buf.append("<rule>\n");
      buf.append("<pattern>");
      buf.append(outputType);
      buf.append("</pattern>\n");
      buf.append("<label>");
      buf.append(label);
      buf.append("</label>\n");
      buf.append("<style>");
      buf.append(STYLES[i % STYLES.length]);
      buf.append("</style>\n");
      buf.append("</rule>\n");
    }

    buf.append("</styleMap>\n");

    return buf.toString();
  }

@SuppressWarnings("unchecked")
	static <T> Expression<T> toExpressionRecursively(From<?, ?> from, PropertyPath property) {

		Bindable<?> propertyPathModel = null;
		Bindable<?> model = from.getModel();
		String segment = property.getSegment();

		if (model instanceof ManagedType) {

			/*
			 *  Required to keep support for EclipseLink 2.4.x. TODO: Remove once we drop that (probably Dijkstra M1)
			 *  See: https://bugs.eclipse.org/bugs/show_bug.cgi?id=413892
			 */
			propertyPathModel = (Bindable<?>) ((ManagedType<?>) model).getAttribute(segment);
		} else {
			propertyPathModel = from.get(segment).getModel();
		}

		if (requiresJoin(propertyPathModel, model instanceof PluralAttribute) && !isAlreadyFetched(from, segment)) {
			Join<?, ?> join = getOrCreateJoin(from, segment);
			return (Expression<T>) (property.hasNext() ? toExpressionRecursively(join, property.next()) : join);
		} else {
			Path<Object> path = from.get(segment);
			return (Expression<T>) (property.hasNext() ? toExpressionRecursively(path, property.next()) : path);
		}
	}

