protected void doRequest(HttpServletRequest request, HttpServletResponse response)
        throws IOException
    {
        Context context = null;
        try
        {
            // prepare needed request and response attributes and properties
            initRequest(request, response);

            // then get a context
            context = createContext(request, response);

            // call standard extension point
            fillContext(context, request);

            setContentType(request, response);

            // get the template
            Template template = handleRequest(request, response, context);

            // merge the template and context into the response
            mergeTemplate(template, context, request, response);
        } catch (IOException e) {
            error(request, response, e);
            throw e;
        }
        catch (ResourceNotFoundException e)
        {
            manageResourceNotFound(request, response, e);
        }
        catch (RuntimeException e)
        {
            error(request, response, e);
            throw e;
        }
        finally
        {
            requestCleanup(request, response, context);
        }
    }

private void drainOutput(HttpURLConnection conn) throws IOException {
		// for things like unauthorised (401) we won't have any content and getting the inputStream will
		// cause an IOException as we are in error - but there is no really way to tell this so check the
		// length instead.
		if (conn.getContentLength() > 0) {
			if (conn.getErrorStream() != null) {
				IOUtils.skip(conn.getErrorStream(), conn.getContentLength());
			}
			else {
				IOUtils.skip(conn.getInputStream(), conn.getContentLength());
			}
		}
	}

