            } catch (NullPointerException npe) {
                value = null;
                if (NestedNullBehavior.THROW == nestedNullBehavior) {
                    throw npe;
                }
            }
            P presentationValue = presentationProvider.apply(value);

            // Make Grid track components.
            if (renderer instanceof ComponentRenderer
