private void setNoCacheHeaders(HttpServletResponse pResp) {
        pResp.setHeader("Cache-Control", "no-cache");
        pResp.setHeader("Pragma","no-cache");
        // Check for a date header and set it accordingly to the recommendations of
        // RFC-2616 (http://tools.ietf.org/html/rfc2616#section-14.21)
        //
        //   "To mark a response as "already expired," an origin server sends an
        //    Expires date that is equal to the Date header value. (See the rules
        //  for expiration calculations in section 13.2.4.)"
        //
        // See also #71

        long now = System.currentTimeMillis();
        pResp.setDateHeader("Date",now);
        // 1h  in the past since it seems, that some servlet set the date header on their
        // own so that it cannot be guaranteed that these headers are really equals.
        // It happened on Tomcat that Date: was finally set *before* Expires: in the final
        // answers some times which seems to be an implementation peculiarity from Tomcat
        pResp.setDateHeader("Expires",now - 3600000);
    }

private void checkMaxSwallowSize() {
        // Parse content-length header
        long contentLength = -1;
        try {
            contentLength = request.getContentLengthLong();
        } catch (Exception e) {
            // Ignore, an error here is already processed in prepareRequest
            // but is done again since the content length is still -1
        }
        if (contentLength > 0 && protocol.getMaxSwallowSize() > -1 &&
                (contentLength - request.getBytesRead() > protocol.getMaxSwallowSize())) {
            // There is more data to swallow than Tomcat will accept so the
            // connection is going to be closed. Disable keep-alive which will
            // trigger adding the "Connection: close" header if not already
            // present.
            keepAlive = false;
        }
    }

protected void waitForActionToComplete(Stage stage) throws StageException {
		log.debug("Waiting for {} to finish transitioning.", stage);
		int i = 0;
		boolean transitioning = false;
		try {
			final URL activityUrl = getRepositoryURL(stage);
			do {
				Document doc = getDocument(activityUrl);
				String status =
				      (String) evaluateXPath("/stagingProfileRepository/transitioning", doc,
				                             XPathConstants.STRING);
				transitioning = Boolean.valueOf(status).booleanValue();
				if (transitioning) {
					i++;
					Thread.sleep(500L);
					if (i % 100 == 0) {
						log.debug("Still waiting for {} to finish transitioning.", stage);
					}
					// TODO should we ever time out?
				}
			} while (transitioning);
		}
		catch (InterruptedException ex) {
			throw new StageException(ex);
		}

	}

