private boolean verifyDataSource(Slice slice, DataSource ds, 
    		JDBCConfiguration conf) {
        Connection con = null;
        try {
            con = ds.getConnection(conf.getConnectionUserName(), 
            		conf.getConnectionPassword());
            slice.setStatus(Slice.Status.ACTIVE);
            if (con == null) {
                slice.setStatus(Slice.Status.INACTIVE);
                return false;
            }
            return true;
        } catch (SQLException ex) {
            slice.setStatus(Slice.Status.INACTIVE);
            return false;
        } finally {
            if (con != null)
                try {
                    con.close();
                } catch (SQLException ex) {
                    // ignore
                }
        }
    }

static String createResourceLocation( final String path, final String name ) {
        Validate.notEmpty( name, "name is empty" );
        final StringBuilder result = new StringBuilder();

        // strip an ending "/"
        final String sanitizedPath = ( path != null && !path.isEmpty() && path.endsWith( "/" ) ? path.substring( 0, path.length() - 1 ) : path );

        // strip leading "/"
        final String sanitizedName = ( name.startsWith( "/" ) ? name.substring( 1 ) : name );

        // append the optional path
        if( sanitizedPath != null && !sanitizedPath.isEmpty() ) {
            if( !sanitizedPath.startsWith( "/" ) ) {
                result.append( "/" );
            }
            result.append( sanitizedPath );
        }
        result.append( "/" );

        // append the name
        result.append( sanitizedName );
        return result.toString();
    }

